INSERT INTO "products" VALUES(9,2,'Thiết bị công nghệ','Siêu xe Porsche 911 GT3 RS (992) Weissach Package','Tuyệt tác tốc độ khí động học chủ động DRS, động cơ 4.0L hút khí tự nhiên 518 mã lực, mâm đúc ma-giê siêu nhẹ, nhập khẩu Đức mới 100%.','{"type": "ThietBiCongNghe", "name": "Siêu xe Porsche 911 GT3 RS (992) Weissach Package", "description": "Tuyệt tác tốc độ khí động học chủ động DRS, động cơ 4.0L hút khí tự nhiên 518 mã lực, mâm đúc ma-giê siêu nhẹ, nhập khẩu Đức mới 100%.", "sellerId": 2, "brand": "Porsche", "model": "911 GT3 RS (992)", "warrantyMonths": 36, "isNew": true, "artist": "", "dimensions": "", "eraCentury": 0, "hasCertificate": false, "isAppraised": false, "medium": "", "origin": "", "preservationState": "", "yearCreated": 0}');
INSERT INTO "products" VALUES(10,2,'Thiết bị công nghệ','Xe địa hình hạng sang Mercedes-AMG G63 V8 Biturbo','Biểu tượng SUV quyền lực động cơ V8 Biturbo 577 mã lực, màu đen Obsidian Metallic, nội thất da Nappa Designo thủ công, Fullbox sổ hãng.','{"type": "ThietBiCongNghe", "name": "Xe địa hình hạng sang Mercedes-AMG G63 V8 Biturbo", "description": "Biểu tượng SUV quyền lực động cơ V8 Biturbo 577 mã lực, màu đen Obsidian Metallic, nội thất da Nappa Designo thủ công, Fullbox sổ hãng.", "sellerId": 2, "brand": "Mercedes-AMG", "model": "G63 V8 Biturbo", "warrantyMonths": 24, "isNew": true, "artist": "", "dimensions": "", "eraCentury": 0, "hasCertificate": false, "isAppraised": false, "medium": "", "origin": "", "preservationState": "", "yearCreated": 0}');
INSERT INTO "products" VALUES(12,2,'Đồ cổ','Trống đồng Đông Sơn Hoàng Gia (Thời kỳ Văn Lang)','Báu vật khảo cổ niên đại hơn 2300 năm, hoa văn ngôi sao mặt trời 14 tia, đàn chim Lạc bay ngược chiều kim đồng hồ, bảo vật quốc gia nguyên bản có kiểm định C-14.','{"type": "DoCo", "name": "Trống đồng Đông Sơn Hoàng Gia (Thời kỳ Văn Lang)", "description": "Báu vật khảo cổ niên đại hơn 2300 năm, hoa văn ngôi sao mặt trời 14 tia, đàn chim Lạc bay ngược chiều kim đồng hồ, bảo vật quốc gia nguyên bản có kiểm định C-14.", "sellerId": 2, "eraCentury": -3, "origin": "Đông Sơn, Thanh Hóa", "preservationState": "Gỉ đồng phong hóa tự nhiên tuyệt đẹp", "isAppraised": true, "artist": "", "brand": "", "dimensions": "", "hasCertificate": false, "isNew": false, "medium": "", "model": "", "warrantyMonths": 0, "yearCreated": 0}');
INSERT INTO "products" VALUES(13,2,'Tranh nghệ thuật','Tranh lụa Thiếu nữ bên hoa huệ - Danh họa Tô Ngọc Vân','Bản phục chế bảo tàng thủ công độc bản trên lụa tơ tằm cổ truyền, tái hiện kiệt tác tiêu biểu của Mỹ thuật Đông Dương với dáng ngồi thiếu nữ Hà thành thanh tao đài các.','{"type": "TranhNgheThuat", "name": "Tranh lụa Thiếu nữ bên hoa huệ - Danh họa Tô Ngọc Vân", "description": "Bản phục chế bảo tàng thủ công độc bản trên lụa tơ tằm cổ truyền, tái hiện kiệt tác tiêu biểu của Mỹ thuật Đông Dương với dáng ngồi thiếu nữ Hà thành thanh tao đài các.", "sellerId": 2, "artist": "Tô Ngọc Vân", "yearCreated": 1943, "medium": "Màu nước trên lụa tơ tằm", "dimensions": "60cm x 90cm", "hasCertificate": true, "brand": "", "eraCentury": 0, "isAppraised": false, "isNew": false, "model": "", "origin": "", "preservationState": "", "warrantyMonths": 0}');
