INSERT INTO "products" VALUES(15,2,'Thiết bị công nghệ','Đồng hồ Rolex Cosmograph Daytona Mặt Số Trắng Panda','Mẫu đồng hồ bấm giờ thể thao cơ khí huyền thoại, vành gốm Cerachrom đen, bộ máy Calibre 4130 đạt chứng nhận Superlative Chronometer, Fullbox thẻ xanh 2024.','{"type": "ThietBiCongNghe", "name": "Đồng hồ Rolex Cosmograph Daytona Mặt Số Trắng Panda", "description": "Mẫu đồng hồ bấm giờ thể thao cơ khí huyền thoại, vành gốm Cerachrom đen, bộ máy Calibre 4130 đạt chứng nhận Superlative Chronometer, Fullbox thẻ xanh 2024.", "sellerId": 2, "brand": "Rolex", "model": "Daytona 116500LN", "warrantyMonths": 60, "isNew": true, "artist": "", "dimensions": "", "eraCentury": 0, "hasCertificate": false, "isAppraised": false, "medium": "", "origin": "", "preservationState": "", "yearCreated": 0}');
INSERT INTO "products" VALUES(16,1,'Thiết bị công nghệ','MacBook Pro 16 inch M3 Max 128GB RAM / 2TB Space Black','Cỗ máy trạm di động đỉnh cao của Apple với 16-core CPU, 40-core GPU, màn hình Liquid Retina XDR 120Hz, vỏ nhôm anot hóa chống bám vân tay, mới 100% nguyên seal.','{"type": "ThietBiCongNghe", "name": "MacBook Pro 16 inch M3 Max 128GB RAM / 2TB Space Black", "description": "Cỗ máy trạm di động đỉnh cao của Apple với 16-core CPU, 40-core GPU, màn hình Liquid Retina XDR 120Hz, vỏ nhôm anot hóa chống bám vân tay, mới 100% nguyên seal.", "sellerId": 1, "brand": "Apple", "model": "MacBook Pro 16 M3 Max", "warrantyMonths": 24, "isNew": true, "artist": "", "dimensions": "", "eraCentury": 0, "hasCertificate": false, "isAppraised": false, "medium": "", "origin": "", "preservationState": "", "yearCreated": 0}');
INSERT INTO "products" VALUES(18,1,'Thiết bị công nghệ','Đồng hồ Patek Philippe Nautilus 5711/1R Vàng Hồng 18K','Kiệt tác Haute Horlogerie Thụy Sĩ vỏ và dây vàng hồng nguyên khối, mặt số nâu chocolate dập vân ngang kinh điển, bộ máy tự động Calibre 324 S C cực kỳ chuẩn xác.','{"type": "ThietBiCongNghe", "name": "Đồng hồ Patek Philippe Nautilus 5711/1R Vàng Hồng 18K", "description": "Kiệt tác Haute Horlogerie Thụy Sĩ vỏ và dây vàng hồng nguyên khối, mặt số nâu chocolate dập vân ngang kinh điển, bộ máy tự động Calibre 324 S C cực kỳ chuẩn xác.", "sellerId": 1, "brand": "Patek Philippe", "model": "Nautilus 5711/1R", "warrantyMonths": 60, "isNew": true, "artist": "", "dimensions": "", "eraCentury": 0, "hasCertificate": false, "isAppraised": false, "medium": "", "origin": "", "preservationState": "", "yearCreated": 0}');
